-- DevTrace schema v1 (Milestone 1): foundation tables.
--
-- Conventions
--   * Identifiers are UUIDv7 strings generated by the application.
--   * Timestamps are fixed-width RFC 3339 UTC strings with millisecond precision
--     (2026-10-22T15:33:42.123Z), generated by the application; lexical order = time order.
--   * Enumerated values (status, review state, assertion, ...) are validated by the Rust
--     domain layer, which is the single source of truth for allowed values. The schema
--     enforces structural invariants (types, non-empty names, JSON validity, references).
--   * Tables are STRICT so SQLite rejects values of the wrong storage type.
--   * Deleting a project never deletes its sessions, playbooks or changes; they become
--     unassigned (ON DELETE SET NULL).
--
-- Later milestones add events, attachments, review decisions and playbook revisions through
-- new migrations. Existing migrations must never be edited after release.

CREATE TABLE app_settings (
    key         TEXT PRIMARY KEY NOT NULL,
    value_json  TEXT NOT NULL CHECK (json_valid(value_json)),
    updated_at  TEXT NOT NULL
) STRICT;

CREATE TABLE projects (
    id           TEXT PRIMARY KEY NOT NULL,
    name         TEXT NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 120),
    description  TEXT NOT NULL DEFAULT '' CHECK (length(description) <= 2000),
    created_at   TEXT NOT NULL,
    updated_at   TEXT NOT NULL
) STRICT;

CREATE UNIQUE INDEX ux_projects_name ON projects (name COLLATE NOCASE);
CREATE INDEX ix_projects_updated_at ON projects (updated_at);

CREATE TABLE sessions (
    id            TEXT PRIMARY KEY NOT NULL,
    project_id    TEXT REFERENCES projects (id) ON DELETE SET NULL,
    title         TEXT NOT NULL CHECK (length(trim(title)) BETWEEN 1 AND 200),
    application   TEXT NOT NULL DEFAULT '',
    environment   TEXT NOT NULL DEFAULT '',
    status        TEXT NOT NULL DEFAULT 'draft',
    review_state  TEXT NOT NULL DEFAULT 'unreviewed',
    notes         TEXT NOT NULL DEFAULT '',
    started_at    TEXT,
    ended_at      TEXT,
    created_at    TEXT NOT NULL,
    updated_at    TEXT NOT NULL
) STRICT;

CREATE INDEX ix_sessions_project_id ON sessions (project_id);
CREATE INDEX ix_sessions_updated_at ON sessions (updated_at);

CREATE TABLE playbooks (
    id               TEXT PRIMARY KEY NOT NULL,
    project_id       TEXT REFERENCES projects (id) ON DELETE SET NULL,
    title            TEXT NOT NULL CHECK (length(trim(title)) BETWEEN 1 AND 200),
    summary          TEXT NOT NULL DEFAULT '',
    status           TEXT NOT NULL DEFAULT 'draft',
    platform         TEXT NOT NULL DEFAULT '',
    product          TEXT NOT NULL DEFAULT '',
    product_version  TEXT NOT NULL DEFAULT '',
    environment      TEXT NOT NULL DEFAULT '',
    task_type        TEXT NOT NULL DEFAULT '',
    author           TEXT NOT NULL DEFAULT '',
    created_at       TEXT NOT NULL,
    updated_at       TEXT NOT NULL,
    published_at     TEXT
) STRICT;

CREATE INDEX ix_playbooks_project_id ON playbooks (project_id);
CREATE INDEX ix_playbooks_status ON playbooks (status);
CREATE INDEX ix_playbooks_updated_at ON playbooks (updated_at);

-- Traceability: which capture sessions a playbook was produced from (many-to-many).
CREATE TABLE playbook_sessions (
    playbook_id  TEXT NOT NULL REFERENCES playbooks (id) ON DELETE CASCADE,
    session_id   TEXT NOT NULL REFERENCES sessions (id) ON DELETE CASCADE,
    linked_at    TEXT NOT NULL,
    PRIMARY KEY (playbook_id, session_id)
) STRICT, WITHOUT ROWID;

CREATE INDEX ix_playbook_sessions_session_id ON playbook_sessions (session_id);

-- Configuration and workflow changes. `assertion` keeps observed activity, declared changes
-- and verified outcomes distinct: observed | declared | verified.
CREATE TABLE change_records (
    id              TEXT PRIMARY KEY NOT NULL,
    project_id      TEXT REFERENCES projects (id) ON DELETE SET NULL,
    session_id      TEXT REFERENCES sessions (id) ON DELETE SET NULL,
    occurred_at     TEXT NOT NULL,
    target          TEXT NOT NULL CHECK (length(trim(target)) BETWEEN 1 AND 300),
    summary         TEXT NOT NULL DEFAULT '',
    environment     TEXT NOT NULL DEFAULT '',
    platform        TEXT NOT NULL DEFAULT '',
    version         TEXT NOT NULL DEFAULT '',
    before_value    TEXT,
    after_value     TEXT,
    assertion       TEXT NOT NULL DEFAULT 'declared',
    approval_state  TEXT NOT NULL DEFAULT 'pending',
    created_at      TEXT NOT NULL,
    updated_at      TEXT NOT NULL
) STRICT;

CREATE INDEX ix_change_records_occurred_at ON change_records (occurred_at);
CREATE INDEX ix_change_records_project_id ON change_records (project_id);
CREATE INDEX ix_change_records_session_id ON change_records (session_id);
